def make(n):
    # generate n distinct invalid spec strings
    invalids = [f"@@invalid{i}@@" for i in range(n)]
    # the benchmark harness will try to build a SpecifierSet with each;
    # we return a single‑element list per call so the harness can iterate.
    return [[s] for s in invalids]

def make(n):
    specs = [f"<={i}.0" for i in range(1, n + 1)]
    return [[", ".join(specs), "2.5"]]

def make(n):
    specs = []
    for i in range(1, n // 2 + 1):
        specs.append(f">={i}.0")
        specs.append(f"<={(i * 2)}.0")
    if len(specs) < n:
        specs.extend([f">={len(specs)+j}.0" for j in range(1, n - len(specs) + 1)])
    return [["," .join(specs[:n]), "1.0"]]
